INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65128011', 65128011, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'UNIT PENYELENGGARA BANDAR UDARA RAHADI OESMAN DI KETAPANG', 'Strip', 'Pekerjaan Konstruksi', 'Penunjukan Langsung', 'Kalimantan Barat, Ketapang (Kab.)', 200000000, 'February 2026', 'APBN - PNBP (D)', 1, 1, '( 1, pkt, @ 200000000 )', 'Belanja pemeliharaan jalan dan jembatan pada area strip bandara berupa kegiatan pemeliharaan rutin dan berkala guna menjaga kondisi permukaan dan area keselamatan penerbangan di sekitar runway, meliputi pembersihan area strip dari FOD, rumput liar, dan genangan air, perataan dan pemadatan permukaan, perbaikan erosi, perawatan drainase, serta perbaikan ringan pada perkerasan/struktur pendukung agar strip bandara tetap memenuhi standar keselamatan dan kelaikan operasi penerbangan.', 'Pekerjaan mencakup pembersihan area strip dari sampah, batu, dan benda asing (FOD), pemotongan rumput dan vegetasi, perataan permukaan tanah, pemadatan kembali area yang bergelombang, perbaikan erosi dan lubang, serta perawatan dan pembersihan saluran drainase di sekitar strip. Termasuk pengamanan area kerja sisi udara, pengaturan waktu kerja agar tidak mengganggu operasional penerbangan, mobilisasi–demobilisasi peralatan, dan pembuangan material sisa pekerjaan. Pelaksanaan harus mengacu pada standar Direktorat Jenderal Perhubungan Udara dan ICAO, menerapkan K3 serta pengendalian FOD, dengan hasil akhir strip bandara bersih, rata, aman, dan memenuhi persyaratan keselamatan penerbangan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 301483);
