INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62944953', 62944953, 'analyze_legacy', 'Provinsi Jawa Barat', 'provinsi', 'Dinas Kelautan dan Perikanan', 'Belanja jasa Pegawai Pemerintah dengan Perjanjian Kerja (PPPK) Paruh Waktu pada jabatan operator layanan operasional (8 orang x 13 bulan)', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Barat, Subang (Kab.)', 466223056, 'January 2026', 'APBD', 1, 1, '104', 'B. Maksud dan Tujuan Cabang Dinas Kelautan Dan Perikanan Wilayah Utara merupakan salah satu organisasi perangkat daerah yang menangani administrasi pelayanan di bidang kelautan dan perikanan, yang memiliki beberapa program kerja dan sasaran strategis. Dalam pencapaian target program kerja dan sasaran strategis dimaksud, didukung dengan beberapa kegiatan dan sarana penunjang yang dilaksanakan oleh Sub Bagian Tata Usaha. Salah satu program penunjang yang dikelola oleh Sub Bagian Tata Usaha adalah Program Penunjang Urusan Pemerintahan Daerah dengan Kegiatan Penyediaan Jasa Penunjang Urusan Pemerintahan Daerah Dengan terlaksananya program dan kegiatan ini diharapkan seluruh kegiatan Penyediaan Jasa Penunjang Urusan Pemerintahan Daerah di Cabang Dinas Kelautan Dan Perikanan Wilayah Utara dapat dilaksanakan secara efektif dan efisien, baik dari aspek efektifitasnya dalam pencapaian tujuan maupun aspek efisiensinya dalam penggunaan anggaran, sehingga sasaran yang hendak dicapai akan tepat sasaran. C. Rencana Target Output 1. Sub Kegiatan : Penyediaan Jasa Pelayanan Umum Kantor yang Disediakan 2. Sasaran Sub Kegiatan : Persentase unit kerja yang terpenuhi kebutuhan Pelayanan Kebersihan, Keamanan, Air, Listrik, Front Office, Driver, dan Komunikasi Terpenuhi 3. Indikator Kinerja Sub Kegiatan : Jumlah Laporan Penyediaan Jasa Pelayanan Umum Kantor yang Disediakan 4. Volume Kinerja Sub Kegiatan (Sub Keluaran/Sub Output) : 12 5. Satuan : Laporan', 'Upah Pegawai Pemerintah dengan Perjanjian Kerja (PPPK) Paruh Waktu Spesifikasi : PPPK Paruh Waktu', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 302022);
